// Lee todos los registros de Posts y decide qué copiar a Supabase.
// NUNCA modifica Airtable: solo genera la consulta de inserción.

const cfg = $('Configuración').first().json;
const threshold = Number(cfg.umbral) || 900;
const target = Number(cfg.objetivo) || 750;
const errorDays = Number(cfg.diasError) || 90;
const alertAfter = Number(cfg.avisoPorEncimaDe) || 950;

const toText = (v) => {
  if (v === null || v === undefined) return '';
  if (Array.isArray(v)) return v.map(toText).join(', ');
  if (typeof v === 'object') return JSON.stringify(v);
  return String(v);
};

const rows = $input.all().map((item) => {
  const f = item.json.fields || item.json;
  return {
    id: item.json.id,
    tema: toText(f['Temas']),
    estado: toText(f['Estado']).trim(),
    fecha_creacion: toText(f['Fecha creación']) || null,
    fecha_publicacion: toText(f['Fecha publicación']) || null,
    fecha_especifica: toText(f['Fecha específica']) || null,
    template_forzado: toText(f['Template forzado']) || null,
    tematica_especifica: toText(f['Temática específica']) || null,
    tipo_escritura: toText(f['Tipo de escritura']) || null,
    estilo_redaccion: toText(f['Estilo de redacción']) || null,
    intencion_articulo: toText(f['Intención del artículo']) || null,
    idioma: toText(f['Idiomas']) || null,
    url_sitio: toText(f['URL del sitio']) || null,
    url_articulo: null,
    payload: f,
  };
});

const now = new Date();
const DAY = 24 * 60 * 60 * 1000;

const dateOf = (r) => {
  const raw = r.fecha_publicacion || r.fecha_creacion;
  if (!raw) return null;
  const d = new Date(raw);
  return Number.isNaN(d.getTime()) ? null : d;
};

const archivable = rows.filter(
  (r) => r.estado === 'Creado' || r.estado === 'Publicado'
);

const oldErrors = rows.filter((r) => {
  if (r.estado !== 'Error') return false;
  const d = dateOf(r);
  return d !== null && now - d > errorDays * DAY;
});

const candidates = archivable.concat(oldErrors).sort((a, b) => {
  const da = dateOf(a);
  const db = dateOf(b);
  if (!da && !db) return 0;
  if (!da) return 1;
  if (!db) return -1;
  return da - db;
});

// Pendientes (No creado / vacío) NUNCA entran en candidates.
const selected = [];
for (const row of candidates) {
  if (rows.length - selected.length <= target) break;
  selected.push(row);
}

const shouldArchive = rows.length > threshold && selected.length > 0;
const alertOnly = !shouldArchive && rows.length > alertAfter;
const shouldRun = shouldArchive || alertOnly;

const esc = (v) => {
  if (v === null || v === undefined || v === '') return 'NULL';
  return "'" + String(v).replace(/'/g, "''") + "'";
};

const jsonEsc = (v) => {
  const raw = JSON.stringify(v === undefined ? null : v);
  return "'" + String(raw).replace(/'/g, "''") + "'::jsonb";
};

const columns = [
  'airtable_id', 'tema', 'url_sitio', 'estado', 'fecha_creacion',
  'fecha_publicacion', 'fecha_especifica', 'template_forzado',
  'tematica_especifica', 'tipo_escritura', 'estilo_redaccion',
  'intencion_articulo', 'url_articulo', 'idioma', 'payload',
];

const values = selected
  .map((r) => '(' + [
    esc(r.id), esc(r.tema), esc(r.url_sitio), esc(r.estado),
    esc(r.fecha_creacion), esc(r.fecha_publicacion), esc(r.fecha_especifica),
    esc(r.template_forzado), esc(r.tematica_especifica), esc(r.tipo_escritura),
    esc(r.estilo_redaccion), esc(r.intencion_articulo), esc(r.url_articulo),
    esc(r.idioma), jsonEsc(r.payload),
  ].join(',') + ')')
  .join(',\n');

const sql = shouldArchive
  ? 'INSERT INTO public.posts_archivo (' + columns.join(', ') + ') VALUES\n' +
    values +
    '\nON CONFLICT (airtable_id) DO NOTHING\nRETURNING airtable_id;'
  : 'SELECT 1;';

const lastDate = selected.length ? dateOf(selected[selected.length - 1]) : null;
const cutoff = lastDate ? lastDate.toISOString().slice(0, 10) : '(sin fecha)';
const totalAfter = rows.length - selected.length;

const byState = {};
for (const r of selected) byState[r.estado] = (byState[r.estado] || 0) + 1;
const breakdown = Object.entries(byState)
  .map(([k, v]) => k + ': ' + v)
  .join(', ');

let message = '';
if (shouldArchive) {
  message = [
    '📦 Archivo de Posts → Supabase',
    '',
    'Registros antes: ' + rows.length,
    'Copiados a Supabase: ' + selected.length + ' (' + breakdown + ')',
    'Quedarían en Airtable tras borrar: ' + totalAfter,
    '',
    'Copia verificada en Supabase antes de borrar.',
    'Corte aplicado: ' + cutoff + ' (Estado Publicado/Creado/Error).',
    'Pendientes ("No creado" o vacío) intactos.',
    '',
    totalAfter > alertAfter
      ? '⚠️ Tras el borrado quedarían ' + totalAfter + ' (> ' + alertAfter +
        '). La mayoría serán pendientes: valora subir de plan.'
      : 'Margen hasta 1.000 registros: ' + (1000 - totalAfter) + '.',
  ].join('\n');
} else if (alertOnly) {
  message = [
    '⚠️ Posts está cerca del límite',
    '',
    'Registros actuales: ' + rows.length,
    'No hay filas archivables (Creado/Publicado/Error antiguas).',
    'El volumen son pendientes. Decide: subir de plan o revisar pendientes antiguos.',
  ].join('\n');
}

return [{
  json: {
    shouldArchive,
    alertOnly,
    shouldRun,
    sql,
    message,
    totalBefore: rows.length,
    totalAfter,
    archived: selected.length,
    ids: selected.map((r) => r.id),
    cutoff,
  },
}];

// Prepara el borrado SOLO de los ids que ya están confirmados en Supabase.
const cfg = $('Seleccionar lote').first().json;
const expected = cfg.ids || [];
const verified = new Set(
  $input.all().map((i) => i.json.airtable_id).filter(Boolean)
);

const deletable = expected.filter((id) => verified.has(id));
const skipped = expected.filter((id) => !verified.has(id));

const BASE = 'appOaontVX9RVfWzd';
const TABLE = 'tblnNFcUahZrNXI7R';
const endpoint = `https://api.airtable.com/v0/${BASE}/${TABLE}`;

const items = [];
for (let i = 0; i < deletable.length; i += 10) {
  const ids = deletable.slice(i, i + 10);
  const qs = ids.map((id) => 'records[]=' + encodeURIComponent(id)).join('&');
  items.push({
    json: {
      ids,
      url: `${endpoint}?${qs}`,
      skip: false,
      totalIds: deletable.length,
      skipped,
      totalAfter: cfg.totalAfter,
    },
  });
}

if (!items.length) {
  items.push({
    json: {
      ids: [],
      url: '',
      skip: true,
      totalIds: 0,
      skipped,
      totalAfter: cfg.totalAfter,
    },
  });
}
return items;

// Cuenta lo que Airtable confirmó como borrado en esta ejecución.
const prep = $('Preparar borrado').first().json;
const deleted = $input.all().reduce(
  (n, i) => n + ((i.json.records || []).length),
  0
);
return [{
  json: {
    deleted,
    totalIds: prep.totalIds,
    totalAfter: prep.totalAfter,
    skipped: prep.skipped || [],
  },
}];
